            <v-divider class="my-2"></v-divider>
            <v-row dense>
              <v-col cols="12">
                <div class="text-caption font-weight-bold grey--text text--darken-2 mb-2">
                  POSITION DETAILS
                </div>
              </v-col>
              <v-col cols="12" sm="6" md="3">
                <div class="text-caption font-weight-bold grey--text text--darken-2 mb-1">
