                </div>
                <div class="text-body-1 font-weight-medium">
                  <v-icon small color="primary">mdi-tag-outline</v-icon>
                  {{ position.department || "—" }}
                </div>
              </v-col>
              <v-col cols="12" sm="6" md="3">
                <div class="text-caption font-weight-bold grey--text text--darken-2 mb-1">
                  FACILITY
                </div>
                <div class="text-body-1 font-weight-medium">
                  <v-icon small color="primary">mdi-hospital-building</v-icon>
                  {{ position.facility || "—" }}
                </div>
              </v-col>
              <v-col cols="12" sm="6" md="3">
                <div class="text-caption font-weight-bold grey--text text--darken-2 mb-1">
                  DISTRICT
                </div>
                <div class="text-body-1 font-weight-medium">
                  <v-icon small color="primary">mdi-map-marker-outline</v-icon>
                  {{ position.district || "—" }}
                </div>
              </v-col>
            </v-row>
          </v-card-text>
        </v-card>

        <!-- ── Review History ───────────────────────────────────────────── -->
        <v-card id="section-history" outlined class="slv-card mb-5">
          <v-card-title
            class="grey darken-3 white--text text-uppercase font-weight-bold d-flex align-center py-3"
          >
            <v-icon left color="white">mdi-timeline-check-outline</v-icon>
            Review History
          </v-card-title>
          <v-card-text class="pa-4">
            <div class="rv-timeline">
              <div
                v-for="stage in timeline"
                :key="stage.code"
                class="rv-timeline-node"
                :class="{ 'rv-timeline-node--done': stage.review }"
              >
                <div
                  class="rv-timeline-node__avatar"
                  :class="{
                    'rv-timeline-node__avatar--rejected': stage.review && stage.review.status === 'rejected',
                    'rv-timeline-node__avatar--approved': stage.review && stage.review.status !== 'rejected',
                    'rv-timeline-node__avatar--current': !stage.review && isCurrentStage(stage),
                  }"
                >
                  <v-icon
                    size="16"
                    :color="stage.review ? 'white' : (isCurrentStage(stage) ? 'white' : '#a8a29e')"
                  >
                    {{
                      stage.review
                        ? (stage.review.status === 'rejected' ? 'mdi-close-circle' : 'mdi-check-circle')
                        : (isCurrentStage(stage) ? 'mdi-clock-outline' : 'mdi-circle-outline')
                    }}
                  </v-icon>
                </div>
                <div class="rv-timeline-node__card">
                  <div class="rv-timeline-node__head">
                    <span class="rv-timeline-node__label">{{ stage.label }}</span>
                    <span
                      v-if="stage.review"
                      class="sl-status-pill sl-status-pill--sm"
                      :class="'sl-status-pill--' + statusKey(stage.review.status)"
                    >
                      {{ stage.review.statusDisplay }}
                    </span>
                    <span v-else-if="isCurrentStage(stage)" class="rv-timeline-node__pending">
                      Awaiting Review
                    </span>
                    <span v-else class="rv-timeline-node__pending rv-timeline-node__pending--muted">
                      Not yet reached
                    </span>
                  </div>
                  <template v-if="stage.review">
                    <div class="rv-timeline-node__meta">
                      {{ stage.review.reviewerName }} · {{ formatDate(stage.review.date) }}
                    </div>
                    <div class="rv-timeline-node__comments" v-if="stage.review.comments">
                      “{{ stage.review.comments }}”
                    </div>
                  </template>
                </div>
              </div>
